    def complete_repository_sized_exports(self):
        """Every canonical tracked path/size, synthetic content, stable real files."""
        for root,prefix in ((self.base,b'old policy\n'),(self.candidate,b'new policy\n')):
            for name,size in CANONICAL_TREE_SIZES:
                target=root/name;target.parent.mkdir(parents=True,exist_ok=True)
                with target.open('wb') as stream:
                    if name==OWNED:stream.write(prefix)
                    stream.truncate(size)
        candidate=g.observe(self.candidate,POLICY['limits'])
        self.facts['manifest_sha256']=g.digest(candidate)
        self.result['artifacts']=[dict(path=OWNED,sha256=next(x['sha256'] for x in candidate if x['path']==OWNED))]
        self.seal()
        return candidate

    def test_complete_canonical_repository_sized_exports_are_consistent(self):
        rows=self.complete_repository_sized_exports();answer=self.assert_consistent()
        self.assertEqual(len(rows),1424);self.assertEqual(sum(x['bytes'] for x in rows),21515651)
        self.assertEqual(max(x['bytes'] for x in rows),5223092)
        self.assertEqual(next(x['bytes'] for x in rows if x['path']=='ISSUE_BROWSER.html'),5223092)
        directories={str(parent) for name,_ in CANONICAL_TREE_SIZES for parent in Path(name).parents if str(parent)!='.'}
        self.assertEqual(len(directories),68);self.assertEqual(len(rows)+len(directories),1492)
        self.assertEqual(answer['decision'],'HOLD');self.assertEqual(answer['effect_authority'],'NONE')

    def test_repository_sized_exports_reject_each_old_inventory_cap(self):
        self.complete_repository_sized_exports();self.assert_consistent()
        for key,value,reason in (('files',512,'ENTRY_BOUND'),('file_bytes',2097152,'FILE_BOUND'),('total_bytes',8388608,'TOTAL_BOUND')):
            with self.subTest(key=key):
                limits=copy.deepcopy(POLICY['limits']);limits[key]=value
                with self.assertRaisesRegex(g.Held,reason):g.observe(self.candidate,limits)

