        self.assertEqual(len(g.observe(root,POLICY['limits'])),2048)
        (root/'overflow').touch()
        with self.assertRaisesRegex(g.Held,'ENTRY_BOUND'):g.observe(root,POLICY['limits'])
        self.assertEqual(len(list(root.iterdir())),2049)

